#!/usr/bin/env python3# -*- coding: utf-8 -*-import chimerafrom chimera import runCommand as rcfrom chimera.selection import currentResiduesimport numpy as npimport fichier as fifrom chimera.specifier import evalSpecfrom Rotamers import getRotamersimport os#Variable Globaldata=fi.lecture("result.txt")AA_mute = data[0]AA_mutepos=" :"+AA_mute[0]+".a"nv_res = AA_mute[2]   pathpdb=str(data[1])#fi.ecriture("result.txt",[str(scoretot)])scoretot=int(data[2][0])seuil_rota = 0.1       #fi.ecriture("result.txt",[str(type(scoretot))]) AA = ["Ala","Arg","Asn","Asp","Cys","Gln","Glu","Gly","His","Ile","Leu","Lys","Met","Phe","Pro","Ser","Thr","Trp","Tyr","Val"]aa_important=[16, 20, 26, 28, 29, 30, 31, 32, 33, 41, 42, 43, 44, 45, 47, 49, 53, 53, 54, 55, 56, 58, 58, 58, 64, 64, 66, 68, 71, 72, 74, 74, 74, 78, 86, 86, 94, 96, 98, 99, 100, 101, 106, 108, 114, 124, 148, 176, 215, 306, 312, 320, 328, 400, 402, 410, 413, 420, 421, 422, 426, 427, 427, 427, 431, 451, 456, 460, 463, 466, 470, 473, 474, 475, 490, 492, 493, 493, 501, 501, 525, 528, 531, 531, 534, 534, 552, 558, 558, 559, 561, 561, 561, 562, 562, 564, 565, 566, 568, 568, 569, 571, 571, 572, 572, 572, 572, 572, 575, 582, 582, 584, 585, 593, 593, 593, 597, 601, 604, 605, 609, 611, 613, 614, 615, 615, 616, 621, 621, 622, 623, 625, 626, 626, 626, 626, 627, 628, 628, 629, 629, 629, 629, 629, 630, 630, 632, 633, 634, 635, 635, 637, 637, 637, 638, 638, 640, 640, 641, 644, 644, 645, 645, 645, 648, 649, 656, 657, 657, 660, 662, 687, 693, 696, 696, 706, 706, 711, 721, 728, 744, 749, 752, 752, 757, 767, 770, 774, 784, 785, 788, 788, 791, 800, 805, 805, 806, 818, 818, 820, 822, 823, 835, 837, 861, 861, 885, 894, 1049, 1066, 1157]aa_important=np.unique(aa_important)                        #Zone de 5 Angstromd={}opened=chimera.openModels.open("C:/Users/Guillaume/Desktop/hERG/hERG_test.pdb")#opened=chimera.openModels.open(pathpdb,type="PDB")mol = opened[0]RES_LIST = mol.residuesrc("select "+AA_mutepos+" za<5") sel_Res = currentResidues()test=[]for res in sel_Res:    test+=[res.id.position]zone_imp=[]for i in test:    if i in aa_important:        zone_imp.append(i)zone=(str(test).replace("[","")).replace("]","")imp_aa=(str(zone_imp).replace("[","")).replace("]","")fi.ecriture(AA_mute[0]+AA_mute[2]+"_result.txt",["5 Angstrom zone Around the aa\n","Zone:\t{}\n".format(zone),"aaImportant:\t{}\n".format(imp_aa)])scoretot=scoretot+(len(zone_imp)*0.5)fi.ecriture(AA_mute[0]+AA_mute[2]+"_result.txt",["\n \nScore après zone:"+str(scoretot)+"\n\n"]) if scoretot >=4:    fi.ecriture("result.txt",["\n"+str(scoretot)])    rc("stop")def extractValeurs(file):    """Extrait les valeurs de probabilités et les nombres de clashs selon le nombre de fichiers à explorer"""    f = open(file,"r")            lines = f.readlines()    fichier=[]    for line in lines :        line=line.split()        if(len(line)==2 and line[1]=="contacts"):            fichier.append(line[0])                 # lecture du nombre de contacts    fichier.append(line[1])                         # lecture de la probabilité du rotamère                           f.close()    os.remove(file)          # suppression des fichiers intermédiaires    return fichierdef extractClash(file):    """Extrait les valeurs de clash et les nombres de clashs selon le nombre de fichiers à explorer"""    f = open(file,"r")            lines = f.readlines()    for line in lines :        line=line.split()        if(len(line)==2 and line[1]=="contacts"):            clash = line[0]     # lecture du nombre de contacts                          f.close()    os.remove(file)          # suppression des fichiers intermédiaires    return clashdef arrondi(x, base=0.5):    return float(base * round(float(x)/base))#fi.ecriture("result.txt",str(AA_mute))rc("swapaa "+nv_res+AA_mutepos)                nbF=0for r in evalSpec(AA_mutepos).residues():    try:                               rots = getRotamers(r)      except:        fi.ecriture(AA_mute[0]+AA_mute[2]+'_result.txt',["\nRotamer\n","No rotamer found \n\nscore_tot = {}".format(scoretot)])        break                   ## gestion d'erreur, un aa peut n'avoir aucun autre rotamère        rc("select "+AA_mutepos+" zr<5")   # sélection des résidus concernés par une zone de 5 angströms autour de l'AA mut    rc("show sel")                  # affichage de leurs chaînes latérales    rc("col purple sel")            # coloration en violet    nb_rotas = len(rots[1])    fi.ecriture(AA_mute[0]+AA_mute[2]+'_result.txt',["Rota\t|\tProba\t\t|\tnbClash\t|\tScore\n"])    scoretotal = 0    probtot = 0    for i in range (0,nb_rotas) :        if(rots[1][i].rotamerProb > seuil_rota):                     # si le seuil d'acceptabilité est dépassé...             rc("swapaa "+nv_res+AA_mutepos+" criteria {}".format(i+1))  # ...l'AA est muté selon le rang du rotamère            rc("addh spec sel")            ## calcul des clashs et écriture dans un fichier            rc("select "+AA_mutepos+" zr<5") # sélection de la zone de calcul de clash            rc("findclash sel test self ignoreIntraRes true colorClashes true clashColor red saveFile clashes{}.txt namingStyle simple summary true log true".format(i+1))            # test self : calcul des clashs entre résidus de la zone seulement             # ignoreIntraRes true : ignore les interactions entre atomes du même résidu            # colorClashes true clashColor red : colorer les clashs en rouge            # saveFile clashes.txt namingStyle simple summary true : écriture des résultats de clashs            ## écriture de la proba du rotamère dans le fichier de clashs            f = open("clashes{}.txt".format(i+1),"a")                    f.write("\np {}".format(rots[1][i].rotamerProb))              f.close()                                                     nbF=nbF+1            valeur_rota=extractValeurs("clashes{}.txt".format(i+1))            if valeur_rota[0]>0:                ### minimisation                rc("addh")                rc("addcharge all")                rc("minimize spec sel prep false freeze unselected nsteps 2 cgsteps 0 interval 5")                rc("findclash sel test self ignoreIntraRes true colorClashes true clashColor red saveFile clashes_min{}.txt namingStyle simple summary true log true".format(i+1))                valeur_rota[0] = extractClash("clashes_min{}.txt".format(i+1))                score_rota = scoretot + 1 + int(float(valeur_rota[0])>0)                scoretotal += arrondi(score_rota*float(valeur_rota[1][:5]))                probtot += float(valeur_rota[1][:5])                #score_rota = scoretot + arrondi(float(valeur_rota[0])*float(valeur_rota[1][:5]))   # génère la liste de scores, pour chaque rotamère                fi.ecriture(AA_mute[0]+AA_mute[2]+"_result.txt",["{}\t|\t{}\t\t|\t{}\t\t|\t{}\tminimisé\n".format(i+1,valeur_rota[1][:5],valeur_rota[0],score_rota)])            else:                score_rota = scoretot + arrondi(float(valeur_rota[0])*float(valeur_rota[1][:5]))   # génère la liste de scores, pour chaque rotamère                scoretotal += arrondi(score_rota*float(valeur_rota[1][:5]))                probtot += float(valeur_rota[1][:5])                fi.ecriture(AA_mute[0]+AA_mute[2]+"_result.txt",["{}\t|\t{}\t\t|\t{}\t\t|\t{}\n".format(i,valeur_rota[1][:5],valeur_rota[0],score_rota)])    scoretotal = arrondi(scoretotal / probtot)    fi.ecriture(AA_mute[0]+AA_mute[2]+"_result.txt",["\n\nScore Final : {}".format(scoretotal)])    scoretot = scoretotal    #Calcul du score totfi.ecriture("result.txt",["\n"+str(scoretot)])rc("stop")